#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    const long long MOD = 998244353;

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }

    vector<long long> factorials(n + 1, 1);
    vector<long long> inverses(n + 1, 1);

    auto modExp = [&](long long base, long long exp, long long mod) {
        long long result = 1;
        long long cur = base % mod;
        while (exp > 0) {
            if (exp & 1) result = (result * cur) % mod;
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return result;
    };

    auto modInverse = [&](long long a, long long m) {
        return modExp(a, m - 2, m);
    };

    for (int i = 1; i <= n; i++) {
        factorials[i] = (i * factorials[i - 1]) % MOD;
        inverses[i] = modInverse(factorials[i], MOD);
    }

    int r = n - (int)k;
    long long totalWays = 0;

    for (int i = 1; i <= r; i++) {
        long long term = factorials[r] * inverses[r - i] % MOD;
        term = term * inverses[i] % MOD;
        term = term * modExp(i, n, MOD) % MOD;
        if ((r - i) % 2 == 1) {
            term = -term;
        }
        totalWays = (totalWays + term + MOD) % MOD;
    }

    if (k == 0) {
        long long result = totalWays * factorials[n] % MOD;
        result = result * inverses[r] % MOD;
        result = result * inverses[n - r] % MOD;
        cout << result << "\n";
    } else {
        long long result = 2 * totalWays % MOD;
        result = result * factorials[n] % MOD;
        result = result * inverses[r] % MOD;
        result = result * inverses[n - r] % MOD;
        cout << result << "\n";
    }

    return 0;
}

